from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (day_available, points) for earned points
        self._earned = {}
        # customer -> total redeemed points
        self._redeemed = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount <= 0:
            raise ValueError("Purchase amount must be positive")
        points = int(amount // 10)
        available_day = day + timedelta(days=14)
        self._earned.setdefault(customer, []).append((available_day, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        earned = sum(
            pts for avail, pts in self._earned.get(customer, [])
            if avail <= day
        )
        redeemed = self._redeemed.get(customer, 0)
        return earned - redeemed

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points % 100 != 0:
            raise ValueError("Points must be redeemed in multiples of 100")
        if points <= 0:
            raise ValueError("Points must be positive")
        if self.balance(customer, day) < points:
            raise ValueError("Insufficient points")
        self._redeemed[customer] = self._redeemed.get(customer, 0) + points
